import { isValidObjectId } from "mongoose";
import { Address } from "../../Models/address.model.js";

export const addAddress = async (req, res) => {
  try {
    const { address, pinCode, status } = req.body;
    if (!address) {
      return res.status(404).json({
        message: "Enter Address",
        success: false
      })
    } else if (!pinCode) {
      return res.status(404).json({
        message: "Enter pinCode",
        success: false
      })
    }

    const addressData = {
      address, pinCode, status
    }
    const response = await Address(addressData);
    await response.save();

    return res.status(200).json({
      message: "Address Added Successfully",
      success: true
    })
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while Adding address",
      success: false
    })
  }
}

export const deleteAddress = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Enter Valid Id",
        success: false
      })
    }
    const operation = await Address.findById(id);
    if (!operation) {
      return res.status(404).json({
        message: "Data not exist in database",
        success: false
      })
    }
    const response = await Address.findByIdAndDelete(id);
    return res.status(200).json({
      message: "Address Deleted Successfully From The database",
      success: true
    });
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while Deleting Address",
      success: false
    })
  }
}


export const viewAddress = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid Id",
        success: false
      })
    }

    const response = await Address.findById(id);
    if (!response) {
      return res.status(404).json({
        message: "Data not exist in database",
        success: false
      })
    }
    return res.status(200).json({
      message: "Address fetched",
      success: true,
      data: response
    })
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while Fetching Data",
      success: false
    })
  }
}

export const editAddress = async (req, res) => {
  try {
    const { id } = req.params;

    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid ID",
        success: false
      })
    }

    const operation = await Address.findById(id);
    if (!operation) {
      return res.status(404).json({
        message: "Data is not exist in database",
        success: false
      })
    }
    const data = {
      address: req.body.address,
      pinCode: req.body.pinCode,
      status: req.body.status,
    }
    const response = await Address.findByIdAndUpdate(id, data, { new: true });
    return res.status(200).json({
      message: "Address Updated Successfully",
      success: true
    })
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while editing Address",
      success: false
    })
  }
}